grant create on schema api,app_private,finance_private to git_tutor_commands;
create table finance_private.financial_remedy_plans(
 id uuid primary key default gen_random_uuid(),source_type text not null check(source_type in('charge','package_consumption')),source_id uuid not null,
 consumption_id uuid references app_private.entitlement_movements(id),policy_version_id uuid not null references app_private.policy_versions(id),proposal_id uuid references app_private.operation_proposals(id),
 approved_by uuid not null references app_private.accounts(id),approved_at timestamptz not null default now(),credit_quanta bigint not null check(credit_quanta between 0 and 9007199254740991),value_minor bigint not null check(value_minor between 0 and 9007199254740991),mode text not null check(mode in('restoration','cash','account_credit')),terms_hash text not null check(terms_hash~'^[a-f0-9]{64}$'),source_ancestry jsonb not null,command_id uuid not null,created_at timestamptz not null default now(),check((source_type='package_consumption')=(consumption_id is not null)),check(consumption_id is null or source_id=consumption_id));
alter table finance_private.financial_remedy_plans enable row level security;
create policy commands_access on finance_private.financial_remedy_plans to git_tutor_commands using(true) with check(true);
grant select,insert on finance_private.financial_remedy_plans to git_tutor_commands;
revoke all on finance_private.financial_remedy_plans from public,anon,authenticated,service_role,git_tutor_worker;
create trigger immutable_financial_remedy before update or delete on finance_private.financial_remedy_plans for each row execute function app_private.refund_source_immutable();
alter table finance_private.remedy_sources add charge_id uuid unique references finance_private.charges(id);

create function api.list_refund_attempts(p_refund_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;begin
 perform app_private.refund_assert_scope(actor,p_refund_id);if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.started_at,'data',jsonb_build_object('attempt_id',x.id,'version',x.version,'state',x.state,'external_reference',x.external_reference,'recorded_at',x.started_at,'settled_at',(select o.settled_at from finance_private.refund_outcomes o where o.attempt_id=x.id and o.outcome='settled'))) order by x.started_at desc,x.id desc),'[]') into rows from(select a.* from finance_private.refund_attempts a where a.refund_id=p_refund_id and(p_cursor is null or(a.started_at,a.id)<(after_at,after_id)) order by a.started_at desc,a.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);end $$;
create function api.list_refund_reversals(p_refund_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;begin
 perform app_private.refund_assert_scope(actor,p_refund_id);if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.recorded_at,'data',jsonb_build_object('refund_reversal_id',x.id,'attempt_id',x.attempt_id,'amount_minor',x.amount_minor,'effective_at',x.effective_at,'recorded_at',x.recorded_at)) order by x.recorded_at desc,x.id desc),'[]') into rows from(select r.* from finance_private.refund_reversals r where r.refund_id=p_refund_id and(p_cursor is null or(r.recorded_at,r.id)<(after_at,after_id)) order by r.recorded_at desc,r.id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);end $$;
create function api.list_refund_remedies(p_refund_id uuid,p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();refund finance_private.refunds%rowtype;after_at timestamptz;after_id uuid;rows jsonb;begin
 refund:=app_private.refund_assert_scope(actor,p_refund_id);if p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('remedy_id',x.id,'title','Approved original-source refund remedy','currency','EGP','remaining_refundable_minor',x.remaining)) order by x.created_at desc,x.id desc),'[]') into rows from(
 select p.*,greatest(0,p.value_minor-coalesce((select sum(r.value_minor) from app_private.remedy_reservations r where r.remedy_id=p.id and r.state in('reserved','consumed')),0)) remaining from finance_private.financial_remedy_plans p where p.mode='cash' and(p.source_type=refund.source_type and p.source_id=refund.source_id or refund.source_type='unapplied_credit' and exists(select 1 from finance_private.payment_allocations a where a.transfer_id=refund.source_id and a.id::text in(select jsonb_array_elements_text(coalesce(p.source_ancestry->'allocation_ids','[]'))))) and(p_cursor is null or(p.created_at,p.id)<(after_at,after_id)) order by p.created_at desc,p.id desc limit p_limit+1)x where x.remaining>0;return app_private.package_page(rows,p_limit);end $$;
create function api.list_refund_sources(p_learner_id uuid default null,p_view text default 'customer',p_cursor text default null,p_limit integer default 25) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();after_at timestamptz;after_id uuid;rows jsonb;begin
 if p_view is null or p_view not in('customer','admin') or p_limit is null or p_limit not between 1 and 100 then raise exception 'VALIDATION_ERROR';end if;if p_view='admin' then perform app_private.require_role(actor,'admin');end if;
 if p_learner_id is not null then perform app_private.package_assert_scope(actor,p_learner_id,'payments',p_view='admin');end if;
 if p_cursor is not null then if length(p_cursor)>200 or array_length(string_to_array(p_cursor,'|'),1)<>2 then raise exception 'VALIDATION_ERROR';end if;after_at:=split_part(p_cursor,'|',1)::timestamptz;after_id:=split_part(p_cursor,'|',2)::uuid;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'at',x.created_at,'data',jsonb_build_object('view',p_view,'source_type',x.source_type,'source_id',x.id,'version',x.version,'title',x.title,'currency','EGP','refundable_minor',x.amount,'requires_remedy',x.requires_remedy)||case when p_view='admin' then jsonb_build_object('payer',app_private.payment_payer_dto(x.payer_account_id)) else jsonb_build_object('payer_is_current_account',x.payer_account_id=actor) end) order by x.created_at desc,x.id desc),'[]') into rows from(
 select * from(
 select t.id,t.created_at,t.version,'unapplied_credit'::text source_type,'Unused incoming funds'::text title,b.payer_account_id,finance_private.finance_refundable_surplus(t.id) amount,false requires_remedy from finance_private.incoming_transfers t join finance_private.transfer_payer_bindings b on b.id=t.current_payer_binding_id where t.state='settled' and(p_view='admin' or b.payer_account_id=actor) and(p_learner_id is null or exists(select 1 from finance_private.payment_allocations a join finance_private.charges c on c.id=a.charge_id where a.transfer_id=t.id and c.learner_id=p_learner_id))
 union all
 select c.id,c.created_at,ca.version,'charge',app_private.payment_charge_dto(c.id)->>'title',min(b.payer_account_id::text)::uuid,sum(a.amount_minor-coalesce((select sum(ar.amount_minor) from finance_private.allocation_reversals ar where ar.allocation_id=a.id),0)),true from finance_private.charges c join finance_private.charge_accounts ca on ca.charge_id=c.id join finance_private.payment_allocations a on a.charge_id=c.id join finance_private.transfer_payer_bindings b on b.id=a.payer_binding_id where(p_learner_id is null or c.learner_id=p_learner_id) and(p_view='admin' or app_private.package_can_access(actor,c.learner_id) or exists(select 1 from finance_private.payment_allocations own_allocation join finance_private.transfer_payer_bindings own_binding on own_binding.id=own_allocation.payer_binding_id where own_allocation.charge_id=c.id and own_binding.payer_account_id=actor)) group by c.id,ca.version having count(distinct b.payer_account_id)=1
 )sources where amount>0 and(p_cursor is null or(created_at,id)<(after_at,after_id)) order by created_at desc,id desc limit p_limit+1)x;return app_private.package_page(rows,p_limit);end $$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='api' and p.proname in('list_refund_sources','list_refund_remedies','list_refund_attempts','list_refund_reversals') loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);execute format('grant execute on function %s to authenticated',f.signature);end loop;end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';

